declare(strict_types=1);require_once __DIR__.'/../auth_check.php';require_once __DIR__.'/../model/Database.php';require_once __DIR__.'/../services/MeetingDailyFollowupService.php';$uid=(int)($_SESSION['user_id']??0);$items=(new MeetingDailyFollowupService(Database::getConnection()))->pendingForUser($uid,new DateTimeImmutable('now'));$clean=static fn(string$v):string=>str_replace(["\\",",",";","\r","\n"],["\\\\","\\,","\\;","","\\n"],$v);$ics="BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//FINEA//Suivi reunions//FR\r\nCALSCALE:GREGORIAN\r\nMETHOD:PUBLISH\r\n";foreach($items as$i=>$item){$date=(string)($item['new_deadline']?:$item['old_deadline']?:date('Y-m-d'));$start=date('Ymd',strtotime($date)).'T080000';$end=date('Ymd',strtotime($date)).'T083000';$summary='Suivi réunion · '.(string)$item['checklist_label'];$details=implode("\n",array_filter([(string)$item['meeting_title'],(string)$item['group_label'],(string)$item['section_title'].' > '.(string)$item['task_title'],'Sous-tâche : '.(string)$item['checklist_label'],'Rôle : '.(string)$item['role_label']]));$ics.="BEGIN:VEVENT\r\nUID:finea-meeting-".(int)$item['checklist_id'].'-'.$uid."@finea\r\nDTSTAMP:".gmdate('Ymd\THis\Z')."\r\nDTSTART:$start\r\nDTEND:$end\r\nSUMMARY:".$clean($summary)."\r\nDESCRIPTION:".$clean($details)."\r\nEND:VEVENT\r\n";}$ics.="END:VCALENDAR\r\n";header('Content-Type: text/calendar; charset=UTF-8');header('Content-Disposition: attachment; filename="engagements_reunions_'.date('Ymd').'.ics"');echo $ics;
